onClick:
{{
  (() => {
    const lien = Get_Facture_ById.data[0]?.Lien_Facture;

    if (!lien) {
      showAlert("Aucun document à imprimer", "warning");
      return;
    }

    // 1. Cas Google Drive (Anciennes factures ou archivage n8n)
    const match = lien.match(/\/d\/([^\/]+)/);
    if (match && match[1]) {
      const fileId = match[1];
      const urlN8n = `http://n8n-aylz3ptk0o2myccjljffrq8n.57.128.185.249.sslip.io/webhook/afficher-pdf?fileId=${fileId}`;
      navigateTo(urlN8n, {}, 'NEW_WINDOW');
      return;
    }

    // 2. Cas Pennylane (Nouvelles factures avec URL complète)
    if (lien.startsWith('http')) {
      navigateTo(lien, {}, 'NEW_WINDOW');
      return;
    }

    // 3. Cas Supabase Storage (Très anciennes factures sans 'http')
    const supabaseUrl = "https://sgubwmfqcmshbyjgaksi.supabase.co/storage/v1/object/public/" + lien;
    navigateTo(supabaseUrl, {}, 'NEW_WINDOW');
  })()
}}
